/// A row: its name in the round's row set, the method's id, the tree constant, the argument's
/// bytes, the proof constant, the tree version, what the jars answer, and the cost counter. The
/// body is `dc 64 <method> <tree> 02 <argument> <proof>`. The answer is the value as `jvm_text`
/// prints it, or `BOUND` (a key or a value that is no collection, refused where it is bound:
/// `EvalError::UnexpectedValue`), `NOPAIR` (an entry that is no pair: `UnexpectedValue`), `CAST`
/// (a key or a value read where the operation is performed: `EvalError::TryExtractFrom`), or
/// `ERR` for any other error
type Row = (
    &'static str,
    u8,
    &'static str,
    &'static str,
    &'static str,
    u8,
    &'static str,
    u64,
);

/// A row that holds its whole body: its name in the review's row sets, the expression's bytes, the
/// tree version, the answer and the cost counter. `BOUND <value>` is a `BOUND` whose refusal
/// names that value
type BodyRow = (&'static str, &'static str, u8, &'static str, u64);

/// What is wrong with one row at one activated version, if anything: its outcome, its value or
/// its cost counter is not the table's
fn wrong(
    name: &str,
    body: &str,
    version: u8,
    expected: &str,
    cost: u64,
    activated: i8,
) -> Option<alloc::string::String> {
    let (res, stopped_at) = eval_body_at(body, ErgoTreeVersion::from(version), activated);
    let as_expected = match (&res, expected) {
        (Err(e), "BOUND") | (Err(e), "NOPAIR") => {
            matches!(innermost(e), EvalError::UnexpectedValue(_))
        }
        (Err(e), "CAST") => matches!(innermost(e), EvalError::TryExtractFrom(_)),
        (Err(_), "ERR") => true,
        (Err(e), named) if named.starts_with("BOUND ") => {
            let text = alloc::format!("expected a collection, found {}", &named[6..]);
            matches!(innermost(e), EvalError::UnexpectedValue(t) if *t == text)
        }
        (Ok(v), text) => jvm_text(v) == text,
        (Err(_), _) => false,
    };
    if as_expected && stopped_at == cost {
        return None;
    }
    Some(alloc::format!(
        "{name} at activated {activated}: expected {expected} at {cost}, got {res:?} at {stopped_at}"
    ))
}

/// Both activated versions of today's blocks. The jars refuse tree version 3 at activated version
/// 2, so those rows are left out there
fn activations(version: u8) -> &'static [i8] {
    if version == 3 {
        &[3]
    } else {
        &[2, 3]
    }
}

fn check(rows: &[Row]) {
    let mut wrongs = alloc::vec::Vec::new();
    for (name, method, tree, argument, proof, version, expected, cost) in rows {
        let body = alloc::format!("dc64{method:02x}{tree}02{argument}{proof}");
        for activated in activations(*version) {
            wrongs.extend(wrong(name, &body, *version, expected, *cost, *activated));
        }
    }
    assert!(
        wrongs.is_empty(),
        "{} runs of {} rows:\n{}",
        wrongs.len(),
        rows.len(),
        wrongs.join("\n")
    );
}

fn check_bodies(rows: &[BodyRow]) {
    let mut wrongs = alloc::vec::Vec::new();
    for (name, body, version, expected, cost) in rows {
        for activated in activations(*version) {
            wrongs.extend(wrong(name, body, *version, expected, *cost, *activated));
        }
    }
    assert!(
        wrongs.is_empty(),
        "{} runs of {} rows:\n{}",
        wrongs.len(),
        rows.len(),
        wrongs.join("\n")
    );
}

